// The YouTube Shorts carousel's logic as plain code: the pure helpers, and a feed class that talks to the
// YouTube Data API through an injected `fetch` (so it is unit-tested with a fake one).
//
// How it finds Shorts (as in the original widget): resolve the channel handle to its "uploads" playlist
// (cheap in API quota, unlike search), read the playlist 50 videos at a time, and keep the videos that
// are short enough to be Shorts (the API has no "is a Short" flag, so duration decides).

const API = 'https://www.googleapis.com/youtube/v3';
/** Videos up to this many seconds count as Shorts (Shorts are <= 180 s; the margin covers rounding). */
export const MAX_SHORT_SECONDS = 185;
/** Keep reading pages until a batch has this many Shorts... */
export const BATCH_TARGET = 5;
/** ...but never spend more than this many reads per batch (quota safety on channels with few Shorts). */
export const MAX_READS_PER_BATCH = 3;

export interface Thumbnail {
  url: string;
}
export interface Video {
  id: string;
  snippet: {
    title: string;
    thumbnails: { maxres?: Thumbnail; high?: Thumbnail; standard?: Thumbnail; medium?: Thumbnail; default: Thumbnail };
  };
  contentDetails: { duration: string };
  statistics: { viewCount?: string };
}

/** "PT1M5S" -> 65. Unparseable -> 0. */
export function parseIsoDuration(duration: string): number {
  const match = duration.match(/PT(?:(\d+)H)?(?:(\d+)M)?(?:(\d+)S)?/);
  if (!match) return 0;
  const hours = parseInt(match[1]) || 0;
  const minutes = parseInt(match[2]) || 0;
  const seconds = parseInt(match[3]) || 0;
  return hours * 3600 + minutes * 60 + seconds;
}

export function isShort(seconds: number): boolean {
  return seconds > 0 && seconds <= MAX_SHORT_SECONDS;
}

/** 1234567 -> "1.2M views"; 5400 -> "5.4K views"; 87 -> "87 views"; none -> "No views". */
export function formatViews(count: string | number | undefined | null): string {
  if (!count) return 'No views';
  const num = parseInt(String(count), 10);
  if (num >= 1000000) return (num / 1000000).toFixed(1).replace(/\.0$/, '') + 'M views';
  if (num >= 1000) return (num / 1000).toFixed(1).replace(/\.0$/, '') + 'K views';
  return num + ' views';
}

/** People often put #shorts in the title; it is dropped for looks. */
export function cleanTitle(title: string): string {
  return title.replace(/#shorts/gi, '').trim();
}

/** The best thumbnail available (the CSS crops a horizontal one to vertical). */
export function bestThumbnail(t: Video['snippet']['thumbnails']): string {
  return (t.maxres || t.high || t.standard || t.medium || t.default).url;
}

/** "RealGoodAI" -> "@RealGoodAI". */
export function channelHandle(identifier: string): string {
  return identifier.startsWith('@') ? identifier : '@' + identifier;
}

/** Thrown for problems the visitor should read (shown in the widget's red box). */
export class ShortsError extends Error {}

type FetchLike = (url: string) => Promise<{ json(): Promise<unknown> }>;
interface ApiError {
  error?: { message: string };
}

export class ShortsFeed {
  private uploadsPlaylistId: string | null = null;
  private nextPageToken: string | null = null;
  private hasMore = true;

  constructor(
    private readonly fetchFn: FetchLike,
    private readonly apiKey: string,
    private readonly identifier: string,
  ) {}

  get done(): boolean {
    return !this.hasMore;
  }

  /** Resolve the channel. Throws ShortsError with the message to show. */
  async init(): Promise<void> {
    if (!this.apiKey) throw new ShortsError('Please configure your YouTube API Key in the widget code.');
    if (!this.identifier) throw new ShortsError('No YouTube channel is configured for this widget.');
    const handle = channelHandle(this.identifier);
    const data = (await (await this.fetchFn(`${API}/channels?part=contentDetails&forHandle=${encodeURIComponent(handle)}&key=${this.apiKey}`)).json()) as ApiError & {
      items?: Array<{ contentDetails: { relatedPlaylists: { uploads: string } } }>;
    };
    if (data.error) throw new ShortsError('Initialization Error: ' + data.error.message);
    if (!data.items || data.items.length === 0) throw new ShortsError('Channel not found. Please verify the handle.');
    this.uploadsPlaylistId = data.items[0].contentDetails.relatedPlaylists.uploads;
  }

  /** The next batch of Shorts (possibly empty); `done` says whether the channel has no more. */
  async nextBatch(): Promise<Video[]> {
    if (!this.hasMore || !this.uploadsPlaylistId) return [];
    const found: Video[] = [];
    let reads = 0;
    try {
      while (found.length < BATCH_TARGET && this.hasMore && reads < MAX_READS_PER_BATCH) {
        reads++;
        let url = `${API}/playlistItems?part=contentDetails&playlistId=${this.uploadsPlaylistId}&maxResults=50&key=${this.apiKey}`;
        if (this.nextPageToken) url += `&pageToken=${this.nextPageToken}`;
        const playlist = (await (await this.fetchFn(url)).json()) as ApiError & {
          nextPageToken?: string;
          items: Array<{ contentDetails: { videoId: string } }>;
        };
        if (playlist.error) throw new Error(playlist.error.message);

        this.nextPageToken = playlist.nextPageToken || null;
        if (!this.nextPageToken) this.hasMore = false;

        const ids = playlist.items.map((item) => item.contentDetails.videoId);
        if (ids.length === 0) continue;

        const videos = (await (await this.fetchFn(`${API}/videos?part=snippet,contentDetails,statistics&id=${ids.join(',')}&key=${this.apiKey}`)).json()) as {
          items?: Video[];
        };
        if (videos.items) found.push(...videos.items.filter((v) => isShort(parseIsoDuration(v.contentDetails.duration))));
      }
    } catch (err) {
      throw new ShortsError('Error loading shorts: ' + (err instanceof Error ? err.message : String(err)));
    }
    return found;
  }
}
