import { BaseElement } from '../../common/base-element';
import { resolveYoutubeChannel, resolveYoutubeKey } from '../../common/runtime-config';
import { cssImageUrl } from '../../campaigns/safe';
import { bestThumbnail, cleanTitle, formatViews, ShortsError, ShortsFeed, type Video } from './shorts';
import { shortsStyles } from './styles';

/**
 * <rg-youtube-shorts>: a horizontally scrolling row of a YouTube channel's Shorts (thumbnail, title, view
 * count; each links to the Short on YouTube). More load as the visitor scrolls to the end.
 *
 *   channel="@name"   optional: the channel to show (default: the site's configured channel)
 *
 * The YouTube Data API key is a browser key from the site's config (restricted to this site's HTTP
 * referrers in Google Cloud). Without one, the widget says it is not configured.
 */
export class RgYoutubeShorts extends BaseElement {
  private observer: IntersectionObserver | undefined;

  constructor() {
    super(shortsStyles);
  }

  static get observedAttributes(): string[] {
    return ['channel'];
  }

  connectedCallback(): void {
    void this.start();
  }

  attributeChangedCallback(): void {
    if (this.isConnected && this.observer) void this.start();
  }

  disconnectedCallback(): void {
    this.observer?.disconnect();
    this.observer = undefined;
  }

  private async start(): Promise<void> {
    this.observer?.disconnect();
    this.setHtml(`
<div id="yt-shorts-widget-container" class="yt-shorts-widget-wrapper">
    <div class="yt-shorts-header">
        <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="#FF0000">
            <path d="M17.77,10.32l-1.2-.5L18,9.06a3.74,3.74,0,0,0-3.5-6.62L6,6.94a3.74,3.74,0,0,0,.23,6.74l1.2.49L6,14.93a3.75,3.75,0,0,0,3.5,6.63l8.5-4.5a3.74,3.74,0,0,0-.23-6.74Z"/>
            <polygon points="10 14.65 15 12 10 9.35 10 14.65" fill="#FFFFFF"/>
        </svg>
        <span class="yt-shorts-widget-title">Shorts</span>
    </div>

    <div class="yt-shorts-error" id="yt-shorts-error" style="display:none;"></div>

    <div class="yt-shorts-scroll-container" id="yt-shorts-container">
        <!-- Short Cards will be injected here -->
        <div class="yt-scroll-sentinel" id="yt-scroll-sentinel">
            <div class="yt-spinner" id="yt-spinner"></div>
        </div>
    </div>
</div>`);

    const container = this.$('#yt-shorts-container')!;
    const sentinel = this.$('#yt-scroll-sentinel')!;
    const spinner = this.$('#yt-spinner')!;
    const errorEl = this.$('#yt-shorts-error')!;
    const showError = (msg: string) => {
      errorEl.textContent = msg;
      errorEl.style.display = 'block';
      spinner.classList.remove('visible');
    };

    const feed = new ShortsFeed((url) => fetch(url), resolveYoutubeKey(), this.getAttribute('channel') || resolveYoutubeChannel());
    let loading = false;

    const loadMore = async () => {
      if (loading || feed.done) return;
      loading = true;
      spinner.classList.add('visible');
      try {
        const shorts = await feed.nextBatch();
        if (shorts.length > 0) this.renderCards(container, sentinel, shorts);
        else if (feed.done && container.children.length <= 1) showError('No Shorts found on this channel.'); // only the sentinel is inside
      } catch (err) {
        showError(err instanceof Error ? err.message : String(err));
      } finally {
        loading = false;
        spinner.classList.remove('visible');
        if (feed.done) sentinel.style.display = 'none'; // finished: hide the loading sentinel
      }
    };

    try {
      await feed.init();
    } catch (err) {
      showError(err instanceof ShortsError ? err.message : 'Initialization Error: ' + (err instanceof Error ? err.message : String(err)));
      return;
    }
    await loadMore();

    // Infinite scrolling: fetch before the visitor reaches the end of the row.
    this.observer = new IntersectionObserver(
      (entries) => {
        if (entries[0].isIntersecting && !feed.done && !loading) void loadMore();
      },
      { root: container, rootMargin: '0px 300px 0px 0px', threshold: 0 },
    );
    this.observer.observe(sentinel);
  }

  private renderCards(container: HTMLElement, sentinel: HTMLElement, videos: Video[]): void {
    for (const video of videos) {
      const card = document.createElement('a');
      card.href = `https://www.youtube.com/shorts/${encodeURIComponent(video.id)}`;
      card.target = '_blank';
      card.className = 'yt-short-card';
      const image = cssImageUrl(bestThumbnail(video.snippet.thumbnails));
      if (image) card.style.backgroundImage = image;

      const playOverlay = document.createElement('div');
      playOverlay.className = 'yt-play-overlay';
      playOverlay.innerHTML = '<svg viewBox="0 0 24 24"><path d="M8 5v14l11-7z"/></svg>';

      const content = document.createElement('div');
      content.className = 'yt-short-content';
      const title = document.createElement('h3');
      title.className = 'yt-short-title';
      title.textContent = cleanTitle(video.snippet.title);
      const views = document.createElement('p');
      views.className = 'yt-short-views';
      views.textContent = formatViews(video.statistics.viewCount);
      content.append(title, views);

      card.append(playOverlay, content);
      container.insertBefore(card, sentinel); // before the sentinel
    }
  }
}

if (!customElements.get('rg-youtube-shorts')) customElements.define('rg-youtube-shorts', RgYoutubeShorts);
